css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; display: grid; grid-template-columns: repeat(4, 1fr); grid-template-rows: repeat(4, 1fr); gap: 0; }
.loader span { position: relative; overflow: hidden; background: color-mix(in srgb, var(--accent) 12%, transparent); animation: truchet-turn calc(var(--loader-speed) * 3.2) ease-in-out infinite; }
.loader span::before { content: ''; position: absolute; left: -50%; top: -50%; width: 100%; height: 100%; border-radius: 50%; box-shadow: 0 0 0 4px var(--accent-2); }
.loader span::after { content: ''; position: absolute; left: 50%; top: 50%; width: 100%; height: 100%; border-radius: 50%; box-shadow: 0 0 0 4px var(--accent); }
.loader span:nth-of-type(2n) { animation-delay: calc(var(--loader-speed) * .2); }
.loader span:nth-of-type(3n) { animation-delay: calc(var(--loader-speed) * .4); }
.loader span:nth-of-type(5n) { animation-delay: calc(var(--loader-speed) * .6); }
.loader span:nth-of-type(7n) { animation-delay: calc(var(--loader-speed) * .8); }
@keyframes truchet-turn { 0%, 18% { transform: rotate(0deg); } 32%, 68% { transform: rotate(90deg); } 82%, 100% { transform: rotate(0deg); } }
